pub fn functionInitSynchronous(
    mut txt: Tpl::Text,
    a_clockedPartitions: &metamodelica::List<SimCode::ClockedPartition>,
    a_modelNamePrefix: &ArcStr,
) -> Result<Tpl::Text> {
    let mut l_body;
    let mut out_txt;
    let mut ret_1;
    let mut ret_2;
    l_body = Tpl::pushIter(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: None,
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    l_body = lm_75(l_body, a_clockedPartitions)?;
    l_body = Tpl::popIter(l_body)?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("/* Initializes the clocks of model. */\n"), literal!("void ")],
            lastHasNewLine: false,
        }),
    )?;
    out_txt = CodegenUtil::symbolName(out_txt, a_modelNamePrefix, &literal!("function_initSynchronous"))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("(DATA *data, threadData_t *threadData)\n"), literal!("{\n")],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("assertStreamPrint(threadData, data->modelData->nBaseClocks=="),
        }),
    )?;
    ret_1 = listLength(a_clockedPartitions.clone());
    out_txt = Tpl::writeStr(out_txt, intString(ret_1))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!(
                    ", \"Number of base clocks doesn't match number of clocks that are initialized! Code generation error!\");\n"
                ),
                literal!("data->simulationInfo->baseClocks = calloc(")
            ],
            lastHasNewLine: false,
        }),
    )?;
    ret_2 = listLength(a_clockedPartitions.clone());
    out_txt = Tpl::writeStr(out_txt, intString(ret_2))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!(", sizeof(BASECLOCK_DATA));\n"), literal!("\n")],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_body)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }),
    )?;
    Ok(out_txt)
}

