    out_txt = Tpl::writeTok(out_txt, metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE))?;
    out_txt = Tpl::writeText(out_txt, l_chunks)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("int "),
        }),
    )?;
    txt_2 = Tpl::writeTok(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("functionEquationsSynchronous_system_"),
        }),
    )?;
