    let mut l_initbody;
    let mut l_initbody__lambda0;
    let mut l_parambody;
    let mut l_body;
    let mut l_jacobianbody;
    let mut out_txt;
    l_initbody = functionInitialMixedSystemsTemp((*Tpl::emptyTxt).clone(), a_initialEquations)?;
    l_initbody__lambda0 = functionInitialMixedSystemsTemp((*Tpl::emptyTxt).clone(), a_initialEquations__lambda0)?;
    l_parambody = functionInitialMixedSystemsTemp((*Tpl::emptyTxt).clone(), a_parameterEquations)?;
    l_body = functionInitialMixedSystemsTemp((*Tpl::emptyTxt).clone(), a_allEquations)?;
    l_jacobianbody = Tpl::pushIter(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)),
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    l_jacobianbody = lm_281(l_jacobianbody, a_jacobianMatrices)?;
    l_jacobianbody = Tpl::popIter(l_jacobianbody)?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![literal!("/* funtion initialize mixed systems */\n"), literal!("void ")],
            lastHasNewLine: false,
        }),
    )?;
    out_txt = CodegenUtil::symbolName(out_txt, a_modelNamePrefix, &literal!("initialMixedSystem"))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("(int nMixedSystems, MIXED_SYSTEM_DATA* mixedSystemData)\n"),
                literal!("{\n"),
                literal!("  /* initial mixed systems */\n")
            ],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
    out_txt = Tpl::writeText(out_txt, l_initbody)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!("/* initial_lambda0 mixed systems */\n"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_initbody__lambda0)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_LINE {
            line: literal!("/* parameter mixed systems */\n"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_parambody)?;
