fn fun_283(mut in_txt: Tpl::Text, in_a_eqn: &metamodelica::Ref<SimCode::SimEqSystem>) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_eqn {
        Deref @ SimCode::SimEqSystem::SES_MIXED { discVars: i_discVars, indexMixedSystem: i_indexMixedSystem, index: i_index, .. } => {
            let mut txt = in_txt;
            let mut ret_1;
            let mut l_size;
            ret_1 = listLength(i_discVars.clone());
            l_size = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_1))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("assertStreamPrint(NULL, nMixedSystems > ") }))?;
            txt = Tpl::writeStr(txt, intString(*i_indexMixedSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(", \"Internal Error: nMixedSystems mismatch!\");\n"), literal!("mixedSystemData[")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_indexMixedSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("].equationIndex = ") }))?;
            txt = Tpl::writeStr(txt, intString(*i_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("mixedSystemData[")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_indexMixedSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("].size = ") }))?;
            txt = Tpl::writeText(txt, l_size)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("mixedSystemData[")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_indexMixedSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("].solveContinuousPart = updateContinuousPart") }))?;
            txt = Tpl::writeStr(txt, intString(*i_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("mixedSystemData[")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_indexMixedSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("].updateIterationExps = updateIterationExpMixedSystem") }))?;
            txt = Tpl::writeStr(txt, intString(*i_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(";") }))?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("fun_283: no case matched"),
    } }
}

