pub fn createGlobalConstraintsFunction(
    mut in_txt: Tpl::Text,
    in_a_system: &metamodelica::Ref<SimCode::SimEqSystem>,
) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_system {
        Deref @ SimCode::SimEqSystem::SES_NONLINEAR { alternativeTearing: Some(Deref @ SimCode::NonlinearSystem { eqs: i_at_eqs, index: i_at_index, .. }), .. } => {
            let mut txt = in_txt;
            let mut l_constraints;
            l_constraints = createGlobalConstraints((*Tpl::emptyTxt).clone(), i_at_eqs)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("int checkConstraints") }))?;
            txt = Tpl::writeStr(txt, intString(*i_at_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("(DATA *data, threadData_t *threadData)\n"), literal!("{\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("const int equationIndexes[2] = {1,") }))?;
            txt = Tpl::writeStr(txt, intString(*i_at_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("};\n") }))?;
            txt = equation_withProfile(txt, &intString(*i_at_index), &Tpl::textString(l_constraints)?)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("return 1;\n") }))?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("}\n"), literal!("\n")], lastHasNewLine: true }))?;
            Ok(txt)
        }
        Deref @ SimCode::SimEqSystem::SES_LINEAR { alternativeTearing: Some(Deref @ SimCode::LinearSystem { residual: i_at_residual, index: i_at_index, .. }), .. } => {
            let mut txt = in_txt;
            let mut l_constraints;
            l_constraints = createGlobalConstraints((*Tpl::emptyTxt).clone(), i_at_residual)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("int checkConstraints") }))?;
            txt = Tpl::writeStr(txt, intString(*i_at_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("(DATA *data, threadData_t *threadData)\n"), literal!("{\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("const int equationIndexes[2] = {1,") }))?;
            txt = Tpl::writeStr(txt, intString(*i_at_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("};\n") }))?;
            txt = equation_withProfile(txt, &intString(*i_at_index), &Tpl::textString(l_constraints)?)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("return 1;\n") }))?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("}\n"), literal!("\n")], lastHasNewLine: true }))?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("createGlobalConstraintsFunction: no case matched"),
    } }
}

