fn fun_363(mut in_txt: Tpl::Text, in_a_con: &metamodelica::Ref<DAE::Constraint>) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match in_a_con {
        Deref @ DAE::Constraint::CONSTRAINT_DT { constraint: i_c, localCon: i_localCon, .. } => {
            let mut txt = in_txt;
            let mut l_preExp;
            let mut l_varDecls;
            let mut l_varFrees;
            let mut l_auxFunction;
            let mut l_condition;
            l_preExp = (*Tpl::emptyTxt).clone();
            l_varDecls = (*Tpl::emptyTxt).clone();
            l_varFrees = (*Tpl::emptyTxt).clone();
            l_auxFunction = (*Tpl::emptyTxt).clone();
            (l_condition, l_preExp, l_varDecls, l_varFrees, l_auxFunction) = CodegenCFunctions::daeExp((*Tpl::emptyTxt).clone(), i_c, &SimCodeFunction::contextSimulationDiscrete(), l_preExp, l_varDecls, l_varFrees, l_auxFunction)?;
            txt = Tpl::writeText(txt, l_varDecls)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeText(txt, l_auxFunction)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeText(txt, l_preExp)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("if (!") }))?;
            txt = Tpl::writeText(txt, l_condition)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("){\n") }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("debugString(OMC_LOG_DT_CONS, \"The following ") }))?;
            txt = fun_362(txt, *i_localCon)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(" constraint is violated:\\n") }))?;
            txt = ExpressionDumpTpl::dumpExp(txt, i_c, &literal!("\""))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("\");\n"), literal!("return 0;\n")], lastHasNewLine: true }))?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }))?;
            Ok(txt)
        }
        _ => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("fun_363: no case matched"),
    } }
}

