fn fun_368(
    mut in_txt: Tpl::Text,
    in_a_eq: &metamodelica::Ref<SimCode::SimEqSystem>,
    mut in_a_eqs: Tpl::Text,
    in_a_modelNamePrefixStr: &ArcStr,
) -> Result<(Tpl::Text, Tpl::Text)> {
    ::match_deref::match_deref! { match (in_a_eq, in_a_modelNamePrefixStr) {
        (Deref @ SimCode::SimEqSystem::SES_RESIDUAL { .. }, _) => {
            let mut txt = in_txt;
            let mut a_eqs = in_a_eqs;
            Ok((txt, a_eqs))
        }
        (Deref @ SimCode::SimEqSystem::SES_FOR_RESIDUAL { .. }, _) => {
            let mut txt = in_txt;
            let mut a_eqs = in_a_eqs;
            Ok((txt, a_eqs))
        }
        (Deref @ SimCode::SimEqSystem::SES_GENERIC_RESIDUAL { .. }, _) => {
            let mut txt = in_txt;
            let mut a_eqs = in_a_eqs;
            Ok((txt, a_eqs))
        }
        (i_eq, a_modelNamePrefixStr) => {
            let mut txt = in_txt;
            let mut a_eqs = in_a_eqs;
            a_eqs = equation_impl(a_eqs, -1, -1, i_eq, &SimCodeFunction::contextSimulationDiscrete(), a_modelNamePrefixStr, false)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("/* local constraints */\n") }))?;
            txt = createLocalConstraints(txt, i_eq)?;
            txt = Tpl::softNewLine(txt)?;
            txt = equation_call(txt, i_eq, a_modelNamePrefixStr, &SimCodeFunction::contextSimulationDiscrete())?;
            txt = Tpl::softNewLine(txt)?;
            txt = CodegenCFunctions::errorCheck(txt, &SimCodeFunction::contextSimulationDiscrete())?;
            Ok((txt, a_eqs))
        }
        _ => Err("fun_368: no case matched"),
    } }
}

