fn fun_422(
    mut in_txt: Tpl::Text,
    in_a_sparsepattern: &metamodelica::List<(i32, metamodelica::List<i32>)>,
    in_a_indexName: &ArcStr,
    in_a_systemType: &ArcStr,
    in_a_colorList: &metamodelica::List<metamodelica::List<i32>>,
    mut in_a_maxColor: i32,
) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match (in_a_sparsepattern, in_a_indexName, in_a_systemType, in_a_colorList, in_a_maxColor) {
        (Deref @ metamodelica::ListNode::Nil, a_indexName, a_systemType, _, _) => {
            let mut txt = in_txt;
            txt = generateStaticEmptySparseData(txt, a_indexName, a_systemType)?;
            Ok(txt)
        }
        (i_sparsepattern, a_indexName, a_systemType, a_colorList, a_maxColor) => {
            let mut txt = in_txt;
            let mut ret_1;
            let mut ret_2;
            let mut l_sp__size__index;
            let mut ret_4;
            let mut l_sizeleadindex;
            let mut ret_6;
            let mut l_colPtr;
            let mut ret_8;
            let mut ret_9;
            let mut l_rowIndex;
            let mut l_colorString;
            ret_1 = List::unzipSecond(i_sparsepattern);
            ret_2 = List::lengthListElements(ret_1);
            l_sp__size__index = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_2))?;
            ret_4 = listLength(i_sparsepattern.clone());
            l_sizeleadindex = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_4))?;
            ret_6 = listLength(i_sparsepattern.clone());
            l_colPtr = genSPCRSPtr((*Tpl::emptyTxt).clone(), ret_6, i_sparsepattern, &literal!("colPtrIndex"))?;
            ret_8 = List::unzipSecond(i_sparsepattern);
            ret_9 = List::lengthListElements(ret_8);
            l_rowIndex = genSPCRSRows((*Tpl::emptyTxt).clone(), ret_9, i_sparsepattern, &literal!("rowIndex"))?;
            l_colorString = genSPColors((*Tpl::emptyTxt).clone(), a_colorList, &literal!("inSysData->sparsePattern->colorCols"))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("\n"), literal!("OMC_DISABLE_OPT\n"), literal!("void initializeSparsePattern")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, a_indexName.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("(") }))?;
            txt = Tpl::writeStr(txt, a_systemType.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("* inSysData)\n"), literal!("{\n"), literal!("  int i=0;\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeText(txt, l_colPtr)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeText(txt, l_rowIndex)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("inSysData->sparsePattern = allocSparsePattern(") }))?;
            txt = Tpl::writeText(txt, l_sizeleadindex.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(", ") }))?;
            txt = Tpl::writeText(txt, l_sp__size__index.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(", ") }))?;
            txt = Tpl::writeStr(txt, intString(a_maxColor))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(");\n"), literal!("\n"), literal!("/* write lead index of compressed sparse column */\n"), literal!("memcpy(inSysData->sparsePattern->leadindex, colPtrIndex, (")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_sizeleadindex.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1)*sizeof(unsigned int));\n"), literal!("\n"), literal!("for(i=2;i<")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_sizeleadindex)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1;++i)\n"), literal!("  inSysData->sparsePattern->leadindex[i] += inSysData->sparsePattern->leadindex[i-1];\n"), literal!("\n"), literal!("/* call sparse index */\n"), literal!("memcpy(inSysData->sparsePattern->index, rowIndex, ")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_sp__size__index)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("*sizeof(unsigned int));\n"), literal!("\n"), literal!("/* write color array */\n")], lastHasNewLine: true }))?;
            txt = Tpl::writeText(txt, l_colorString)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }))?;
            Ok(txt)
        }
        _ => Err("fun_422: no case matched"),
    } }
}

