pub fn generateStaticEmptyNonlinearData(
    mut txt: Tpl::Text,
    a_indexName: &ArcStr,
    a_systemType: &ArcStr,
) -> Result<Tpl::Text> {
    let mut out_txt;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("void initializeNonlinearPattern"),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_indexName.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("(") }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_systemType.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("* inSysData)\n"),
                literal!("{\n"),
                literal!("  /* no nonlinear pattern available */\n"),
                literal!("}")
            ],
            lastHasNewLine: false,
        }),
    )?;
    Ok(out_txt)
}

fn fun_425(
    mut in_txt: Tpl::Text,
    in_a_nonlinearpattern: &metamodelica::List<(i32, metamodelica::List<i32>)>,
    in_a_indexName: &ArcStr,
    in_a_systemType: &ArcStr,
    in_a_nonlinearpatternT: &metamodelica::List<(i32, metamodelica::List<i32>)>,
) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match (in_a_nonlinearpattern, in_a_indexName, in_a_systemType, in_a_nonlinearpatternT) {
        (Deref @ metamodelica::ListNode::Nil, a_indexName, a_systemType, _) => {
            let mut txt = in_txt;
            txt = generateStaticEmptyNonlinearData(txt, a_indexName, a_systemType)?;
            Ok(txt)
        }
        (i_nonlinearpattern, a_indexName, a_systemType, a_nonlinearpatternT) => {
            let mut txt = in_txt;
            let mut ret_1;
            let mut l_number__vars;
            let mut ret_3;
            let mut l_number__eqns;
            let mut ret_5;
            let mut ret_6;
            let mut l_number__nonlinear;
            let mut ret_8;
            let mut l_index__var;
            let mut ret_10;
            let mut l_index__eqn;
            let mut ret_12;
            let mut ret_13;
            let mut l_columns;
            let mut ret_15;
            let mut ret_16;
            let mut l_rows;
            ret_1 = listLength(a_nonlinearpatternT.clone());
            l_number__vars = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_1))?;
            ret_3 = listLength(i_nonlinearpattern.clone());
            l_number__eqns = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_3))?;
            ret_5 = List::unzipSecond(i_nonlinearpattern);
            ret_6 = List::lengthListElements(ret_5);
            l_number__nonlinear = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_6))?;
            ret_8 = listLength(a_nonlinearpatternT.clone());
            l_index__var = genSPCRSPtr((*Tpl::emptyTxt).clone(), ret_8, a_nonlinearpatternT, &literal!("index_var"))?;
            ret_10 = listLength(a_nonlinearpatternT.clone());
            l_index__eqn = genSPCRSPtr((*Tpl::emptyTxt).clone(), ret_10, a_nonlinearpatternT, &literal!("index_eqn"))?;
            ret_12 = List::unzipSecond(a_nonlinearpatternT);
            ret_13 = List::lengthListElements(ret_12);
            l_columns = genSPCRSRows((*Tpl::emptyTxt).clone(), ret_13, a_nonlinearpatternT, &literal!("columns"))?;
            ret_15 = List::unzipSecond(i_nonlinearpattern);
            ret_16 = List::lengthListElements(ret_15);
            l_rows = genSPCRSRows((*Tpl::emptyTxt).clone(), ret_16, i_nonlinearpattern, &literal!("rows"))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("OMC_DISABLE_OPT\n"), literal!("void initializeNonlinearPattern")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, a_indexName.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("(") }))?;
            txt = Tpl::writeStr(txt, a_systemType.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("* inSysData)\n"), literal!("{\n"), literal!("  int i=0;\n"), literal!("  inSysData->nonlinearPattern = (NONLINEAR_PATTERN*) malloc(sizeof(NONLINEAR_PATTERN));\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("inSysData->nonlinearPattern->numberOfVars = ") }))?;
            txt = Tpl::writeText(txt, l_number__vars.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("inSysData->nonlinearPattern->numberOfEqns = ")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__eqns.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("inSysData->nonlinearPattern->numberOfNonlinear = ")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__nonlinear.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(";\n"), literal!("inSysData->nonlinearPattern->indexVar = (unsigned int*) malloc((")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__vars.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1)*sizeof(unsigned int));\n"), literal!("inSysData->nonlinearPattern->indexEqn = (unsigned int*) malloc((")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__eqns.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1)*sizeof(unsigned int));\n"), literal!("inSysData->nonlinearPattern->columns = (unsigned int*) malloc(")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__nonlinear.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("*sizeof(unsigned int));\n"), literal!("inSysData->nonlinearPattern->rows = (unsigned int*) malloc(")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__nonlinear.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("*sizeof(unsigned int));\n"), literal!("/* initialize and accumulate index vectors */\n")], lastHasNewLine: true }))?;
            txt = Tpl::writeText(txt, l_index__var)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeText(txt, l_index__eqn)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("memcpy(inSysData->nonlinearPattern->indexVar, index_var, (") }))?;
            txt = Tpl::writeText(txt, l_number__vars.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1)*sizeof(unsigned int));\n"), literal!("memcpy(inSysData->nonlinearPattern->indexEqn, index_eqn, (")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__eqns.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1)*sizeof(unsigned int));\n"), literal!("for(i=2;i<")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__vars)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1;++i)\n"), literal!("  inSysData->nonlinearPattern->indexVar[i] += inSysData->nonlinearPattern->indexVar[i-1];\n"), literal!("for(i=2;i<")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__eqns)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("+1;++i)\n"), literal!("  inSysData->nonlinearPattern->indexEqn[i] += inSysData->nonlinearPattern->indexEqn[i-1];\n"), literal!("/* initialize columns and rows */\n")], lastHasNewLine: true }))?;
            txt = Tpl::writeText(txt, l_columns)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeText(txt, l_rows)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("memcpy(inSysData->nonlinearPattern->columns, columns, ") }))?;
            txt = Tpl::writeText(txt, l_number__nonlinear.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("*sizeof(unsigned int));\n"), literal!("memcpy(inSysData->nonlinearPattern->rows, rows, ")], lastHasNewLine: false }))?;
            txt = Tpl::writeText(txt, l_number__nonlinear)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("*sizeof(unsigned int));\n") }))?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("}") }))?;
            Ok(txt)
        }
        _ => Err("fun_425: no case matched"),
    } }
}

pub fn generateStaticNonlinearData(
    mut txt: Tpl::Text,
    a_indexName: &ArcStr,
    a_systemType: &ArcStr,
    a_nonlinearpattern: &metamodelica::List<(i32, metamodelica::List<i32>)>,
    a_nonlinearpatternT: &metamodelica::List<(i32, metamodelica::List<i32>)>,
) -> Result<Tpl::Text> {
    let mut out_txt;
    out_txt = fun_425(txt, a_nonlinearpattern, a_indexName, a_systemType, a_nonlinearpatternT)?;
    Ok(out_txt)
}

