pub fn functionXXX_system0_HPCOM_PThread_func(
    mut txt: Tpl::Text,
    a_derivativEquations: &metamodelica::List<metamodelica::Ref<SimCode::SimEqSystem>>,
    a_name: &ArcStr,
    mut a_n: i32,
    a_threadTasks: &metamodelica::Array<metamodelica::List<metamodelica::Ref<HpcOmSimCode::Task>>>,
    a_iType: &ArcStr,
    mut a_idx: i32,
    a_modelNamePrefixStr: &ArcStr,
) -> Result<Tpl::Text> {
    let mut ret_1;
    let mut ret_2;
    let mut l_taskEqs;
    let mut l_assLock;
    let mut l_relLock;
    let mut out_txt;
    ret_1 = intAdd(a_idx, 1);
    ret_2 = arrayGet(a_threadTasks.clone(), ret_1)?;
    l_taskEqs = functionXXX_system0_HPCOM_Thread0(
        (*Tpl::emptyTxt).clone(),
        a_derivativEquations,
        a_name,
        &ret_2,
        a_iType,
        a_modelNamePrefixStr,
    )?;
    l_assLock = function_HPCOM_assignLockByLockName(
        (*Tpl::emptyTxt).clone(),
        &intString(a_idx),
        &literal!("th_lock"),
        &literal!("pthreads"),
    )?;
    l_relLock = function_HPCOM_releaseLockByLockName(
        (*Tpl::emptyTxt).clone(),
        &intString(a_idx),
        &literal!("th_lock1"),
        &literal!("pthreads"),
    )?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("void* function"),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_name.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("_system"),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, intString(a_n))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("_thread_"),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, intString(a_idx))?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("(void *arg)\n"),
                literal!("{\n"),
                literal!("  DATA *data = (DATA*) arg;\n"),
                literal!("  OMC_TRY_TOP()\n"),
                literal!("  while(1)\n"),
                literal!("  {\n")
            ],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::pushBlock(out_txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 4 }))?;
    out_txt = Tpl::writeText(out_txt, l_assLock)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("\n"),
                literal!("if(finished)\n"),
                literal!("   return NULL;\n"),
                literal!("\n")
            ],
            lastHasNewLine: true,
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_taskEqs)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::writeText(out_txt, l_relLock)?;
    out_txt = Tpl::softNewLine(out_txt)?;
    out_txt = Tpl::popBlock(out_txt)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST {
            strList: metamodelica::list![
                literal!("  }\n"),
                literal!("  OMC_CATCH_TOP(return NULL;) /* No exit status?? */\n"),
                literal!("}")
            ],
            lastHasNewLine: false,
        }),
    )?;
    Ok(out_txt)
}

