pub fn genVarIndexes(
    mut txt: Tpl::Text,
    a_vars: &metamodelica::List<metamodelica::Ref<SimCodeVar::SimVar>>,
    a_arrayName: &ArcStr,
) -> Result<Tpl::Text> {
    let mut ret_1;
    let mut l_size;
    let mut l_varIndexes;
    let mut out_txt;
    ret_1 = listLength(a_vars.clone());
    l_size = Tpl::writeStr((*Tpl::emptyTxt).clone(), intString(ret_1))?;
    l_varIndexes = Tpl::pushIter(
        (*Tpl::emptyTxt).clone(),
        metamodelica::Ref::new(Tpl::IterOptions {
            startIndex0: 0,
            empty: None,
            separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
                value: literal!(","),
            })),
            alignNum: 0,
            alignOfset: 0,
            alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
            wrapWidth: 0,
            wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE),
        }),
    )?;
    l_varIndexes = lm_613(l_varIndexes, a_vars)?;
    l_varIndexes = Tpl::popIter(l_varIndexes)?;
    out_txt = Tpl::writeTok(
        txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("const int "),
        }),
    )?;
    out_txt = Tpl::writeStr(out_txt, a_arrayName.clone())?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("[") }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_size)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING {
            value: literal!("] = {"),
        }),
    )?;
    out_txt = Tpl::writeText(out_txt, l_varIndexes)?;
    out_txt = Tpl::writeTok(
        out_txt,
        metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("};") }),
    )?;
    Ok(out_txt)
}

