fn fun_696(
    mut in_txt: Tpl::Text,
    in_a_var: &metamodelica::Ref<SimCodeVar::SimVar>,
    mut in_a_arrindex: i32,
    in_a_arrayName: &ArcStr,
) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match (in_a_var, in_a_arrindex, in_a_arrayName) {
        (Deref @ SimCodeVar::SimVar { name: i_name, .. }, a_arrindex, a_arrayName) => {
            let mut txt = in_txt;
            let mut txt_0;
            let mut txt_1;
            let mut ret_2;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("\"  Real '") }))?;
            txt = Tpl::writeStr(txt, a_arrayName.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("_") }))?;
            txt_0 = CodegenUtil::crefStrNoUnderscore((*Tpl::emptyTxt).clone(), i_name)?;
            txt_1 = CodegenUtil::escapeSingleQuoteIdent((*Tpl::emptyTxt).clone(), &Tpl::textString(txt_0)?)?;
            ret_2 = Util::escapeModelicaStringToCString(Tpl::textString(txt_1)?);
            txt = Tpl::writeStr(txt, ret_2)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("' = ") }))?;
            txt = Tpl::writeStr(txt, a_arrayName.clone())?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("[") }))?;
            txt = Tpl::writeStr(txt, intString(a_arrindex))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("];\\n\"") }))?;
            Ok(txt)
        }
        (_, _, _) => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("fun_696: no case matched"),
    } }
}

