            txt = CodegenUtil::symbolName(txt, a_modelNamePrefix, &literal!("eqFunction"))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("_") }))?;
            txt = Tpl::writeText(txt, l_ix)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("(data, threadData);\n"), literal!("function")], lastHasNewLine: false }))?;
