pub fn equationAlgorithm(
    mut in_txt: Tpl::Text,
    in_a_eq: &metamodelica::Ref<SimCode::SimEqSystem>,
    in_a_context: &SimCodeFunction::Context,
    mut in_a_varDecls: Tpl::Text,
    mut in_a_varFrees: Tpl::Text,
    mut in_a_auxFunction: Tpl::Text,
) -> Result<(Tpl::Text, Tpl::Text, Tpl::Text, Tpl::Text)> {
    ::match_deref::match_deref! { match (in_a_eq, in_a_context) {
        (Deref @ SimCode::SimEqSystem::SES_INVERSE_ALGORITHM { insideNonLinearSystem: true, statements: i_statements, .. }, a_context) => {
            let mut txt = in_txt;
            let mut a_varDecls = in_a_varDecls;
            let mut a_varFrees = in_a_varFrees;
            let mut a_auxFunction = in_a_auxFunction;
            txt = Tpl::pushIter(txt, metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (txt, a_auxFunction, a_varFrees, a_varDecls) = lm_993(txt, i_statements, a_auxFunction, a_varFrees, a_varDecls, a_context)?;
            txt = Tpl::popIter(txt)?;
            Ok((txt, a_varDecls, a_varFrees, a_auxFunction))
        }
        (Deref @ SimCode::SimEqSystem::SES_ALGORITHM { statements: i_statements, .. }, a_context) => {
            let mut txt = in_txt;
            let mut a_varDecls = in_a_varDecls;
            let mut a_varFrees = in_a_varFrees;
            let mut a_auxFunction = in_a_auxFunction;
            txt = Tpl::pushIter(txt, metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (txt, a_auxFunction, a_varFrees, a_varDecls) = lm_994(txt, i_statements, a_auxFunction, a_varFrees, a_varDecls, a_context)?;
            txt = Tpl::popIter(txt)?;
            Ok((txt, a_varDecls, a_varFrees, a_auxFunction))
        }
        (Deref @ SimCode::SimEqSystem::SES_INVERSE_ALGORITHM { knownOutputCrefs: i_alg_knownOutputCrefs, statements: i_statements, .. }, a_context) => {
            let mut txt = in_txt;
            let mut a_varDecls = in_a_varDecls;
            let mut a_varFrees = in_a_varFrees;
            let mut a_auxFunction = in_a_auxFunction;
            let mut l_sub;
            let mut l_backupKnown;
            let mut l_stmts;
            let mut l_restoreKnownVars;
            l_sub = (*Tpl::emptyTxt).clone();
            l_backupKnown = Tpl::pushIter((*Tpl::emptyTxt).clone(), metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (l_backupKnown, l_sub, a_varDecls) = lm_995(l_backupKnown, i_alg_knownOutputCrefs, l_sub, a_varDecls)?;
            l_backupKnown = Tpl::popIter(l_backupKnown)?;
            l_stmts = Tpl::pushIter((*Tpl::emptyTxt).clone(), metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (l_stmts, a_auxFunction, a_varFrees, a_varDecls) = lm_996(l_stmts, i_statements, a_auxFunction, a_varFrees, a_varDecls, a_context)?;
            l_stmts = Tpl::popIter(l_stmts)?;
            l_restoreKnownVars = Tpl::pushIter((*Tpl::emptyTxt).clone(), metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (l_restoreKnownVars, l_sub) = lm_997(l_restoreKnownVars, i_alg_knownOutputCrefs, l_sub)?;
            l_restoreKnownVars = Tpl::popIter(l_restoreKnownVars)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("/* backup outputs of the algorithm */\n") }))?;
            txt = Tpl::writeText(txt, l_backupKnown)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("/* algrithm it self */\n") }))?;
            txt = Tpl::writeText(txt, l_stmts)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!("/* restore outputs of the algorithm */\n") }))?;
            txt = Tpl::writeText(txt, l_restoreKnownVars)?;
            Ok((txt, a_varDecls, a_varFrees, a_auxFunction))
        }
        (_, _) => {
            let mut txt = in_txt;
            let mut a_varDecls = in_a_varDecls;
            let mut a_varFrees = in_a_varFrees;
            let mut a_auxFunction = in_a_auxFunction;
            Ok((txt, a_varDecls, a_varFrees, a_auxFunction))
        }
        _ => Err("equationAlgorithm: no case matched"),
    } }
}

