fn fun_1007(
    mut in_txt: Tpl::Text,
    in_a_eq: &metamodelica::Ref<SimCode::SimEqSystem>,
    in_a_context: &SimCodeFunction::Context,
) -> Result<Tpl::Text> {
    ::match_deref::match_deref! { match (in_a_eq, in_a_context) {
        (Deref @ SimCode::SimEqSystem::SES_LINEAR { lSystem: Deref @ SimCode::LinearSystem { vars: i_ls_vars, index: i_ls_index, partOfJac: i_ls_partOfJac, indexLinearSystem: i_ls_indexLinearSystem, .. }, alternativeTearing: i_at, .. }, a_context) => {
            let mut txt = in_txt;
            let mut l_returnval;
            let mut l_returnval2;
            let mut l_auxFunctions;
            let mut ret_3;
            let mut ret_4;
            let mut ret_5;
            let mut ret_6;
            let mut ret_7;
            l_returnval = fun_999((*Tpl::emptyTxt).clone(), i_at)?;
            l_returnval2 = fun_1000((*Tpl::emptyTxt).clone(), i_at)?;
            l_auxFunctions = (*Tpl::emptyTxt).clone();
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("/* Linear equation system */\n"), literal!("int retValue;\n"), literal!("double aux_x[")], lastHasNewLine: false }))?;
            ret_3 = listLength(i_ls_vars.clone());
            txt = Tpl::writeStr(txt, intString(ret_3))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("] = { ") }))?;
            txt = Tpl::pushIter(txt, metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!(",") })), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (txt, l_auxFunctions) = lm_1001(txt, i_ls_vars, l_auxFunctions, a_context)?;
            txt = Tpl::popIter(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(" };\n"), literal!("infoStreamPrint(OMC_LOG_DT, 0, \"Solving linear system ")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_ls_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_LINE { line: literal!(" (STRICT TEARING SET if tearing enabled) at time = %18.10e\", data->localData[0]->timeValue);\n") }))?;
            ret_4 = Config::profileSome()?;
            txt = fun_1002(txt, ret_4, *i_ls_index)?;
            txt = Tpl::softNewLine(txt)?;
            txt = fun_1003(txt, *i_ls_partOfJac, *i_ls_indexLinearSystem)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("\n"), literal!("retValue = ")], lastHasNewLine: false }))?;
            ret_5 = listLength(i_ls_vars.clone());
            ret_6 = intEq(ret_5, 1);
            txt = fun_1004(txt, ret_6)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("(data, threadData, ") }))?;
            txt = Tpl::writeStr(txt, intString(*i_ls_indexLinearSystem))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(", &aux_x[0]);\n"), literal!("\n"), literal!("/* check if solution process was successful */\n"), literal!("if (retValue > 0){\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushBlock(txt, metamodelica::Ref::new(Tpl::BlockType::BT_INDENT { width: 2 }))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING { value: literal!("const int indexes[2] = {1,") }))?;
            txt = Tpl::writeStr(txt, intString(*i_ls_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("};\n"), literal!("raiseStreamPrintWithEquationIndexes(threadData, omc_dummyFileInfo, indexes, \"Solving linear system ")], lastHasNewLine: false }))?;
            txt = Tpl::writeStr(txt, intString(*i_ls_index))?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!(" failed at time=%.15g.\\nFor more information please use -lv LOG_LS.\", data->localData[0]->timeValue);\n"), literal!("OMC_ERROR_CHECK();\n")], lastHasNewLine: true }))?;
            txt = Tpl::writeText(txt, l_returnval2)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::popBlock(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_STRING_LIST { strList: metamodelica::list![literal!("}\n"), literal!("/* write solution */\n")], lastHasNewLine: true }))?;
            txt = Tpl::pushIter(txt, metamodelica::Ref::new(Tpl::IterOptions { startIndex0: 0, empty: None, separator: Some(metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE)), alignNum: 0, alignOfset: 0, alignSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE), wrapWidth: 0, wrapSeparator: metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE) }))?;
            (txt, l_auxFunctions) = lm_1005(txt, i_ls_vars, l_auxFunctions, a_context)?;
            txt = Tpl::popIter(txt)?;
            txt = Tpl::softNewLine(txt)?;
            ret_7 = Config::profileSome()?;
            txt = fun_1006(txt, ret_7, *i_ls_index)?;
            txt = Tpl::softNewLine(txt)?;
            txt = Tpl::writeTok(txt, metamodelica::Ref::new(Tpl::StringToken::ST_NEW_LINE))?;
            txt = Tpl::writeText(txt, l_returnval)?;
            Ok(txt)
        }
        (_, _) => {
            let mut txt = in_txt;
            Ok(txt)
        }
        _ => Err("fun_1007: no case matched"),
    } }
}

